mapper.insert:
INSERT INTO resumes (
    user_id
    , title
    , template_id
    , created_at
    , updated_at
) VALUES (
    #{userId}
    , #{title}
    , #{templateId}
    , CURRENT_TIMESTAMP
    , CURRENT_TIMESTAMP
)

INSERT INTO resume_profile (
    resume_id
    , name
    , email
    , phone
    , address
    , profile_image
    , birth_date
    , introduction
) VALUES (
    #{resumeId}
    , #{name}
    , #{email}
    , #{phone}
    , #{address}
    , #{profileImage}
    , #{birthDate}
    , #{introduction}
)

INSERT INTO resume_skill (
    resume_id,
    skill_name,
    sort_order
) VALUES (
    #{resumeId},
    #{skillName},
    #{sortOrder}
)
